const select=typeof document!=='undefined'?document.getElementById('ui-language'):null;
const originals=new WeakMap();
const attributeOriginals=new WeakMap();
const initialTitle=typeof document!=='undefined'?document.title:null;
function applyAttributes(lang){
 if(typeof document==='undefined'||typeof document.querySelectorAll!=='function')return;
 for(const node of document.querySelectorAll('[placeholder],[aria-label]')){
   let entries=attributeOriginals.get(node);
   if(!entries){entries={};attributeOriginals.set(node,entries);}
   for(const attribute of ['placeholder','aria-label']){
     if(!node.hasAttribute(attribute))continue;
     if(!Object.hasOwn(entries,attribute))entries[attribute]=node.getAttribute(attribute);
     const original=entries[attribute];
     if(Object.hasOwn(DICTIONARIES.en,original))node.setAttribute(attribute,DICTIONARIES[lang]?.[original]||original);
   }
 }
 if(typeof initialTitle==='string'&&Object.hasOwn(DICTIONARIES.en,initialTitle))document.title=DICTIONARIES[lang]?.[initialTitle]||initialTitle;
}
const excluded='textarea,input,code,pre,script,style,#result-area,#citation-results,#quality-last,#run,#source-label,#equation-help,#evidence-method-tag,#coverage-panel,#field-confirm-panel,[contenteditable]';
function applyExtended(lang){
 const dict=DICTIONARIES[Object.hasOwn(DICTIONARIES,lang)?lang:'en'];
 applyAttributes(Object.hasOwn(DICTIONARIES,lang)?lang:'en');
 const iterator=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);
 let node;
 while((node=iterator.nextNode())){
  const parent=node.parentElement;
  if(!parent||parent.closest(excluded))continue;
  const raw=originals.get(node)??node.nodeValue;
  const normalized=raw.trim();
  if(!Object.hasOwn(DICTIONARIES.en,normalized))continue;
  if(!originals.has(node))originals.set(node,raw);
  const leading=raw.match(/^\s*/)[0],trailing=raw.match(/\s*$/)[0];
  node.nodeValue=leading+dict[normalized]+trailing;
 }
}
if(select){
 const requested=typeof location!=='undefined'?new URLSearchParams(location.search).get('lang'):null;
 if(requested&&Object.hasOwn(DICTIONARIES,requested))select.value=requested;
 select.addEventListener('change',()=>{applyExtended(select.value);document.documentElement.lang=select.value;updateGuideLinks(select.value);});
 applyExtended(select.value);
 document.documentElement.lang=select.value;
 updateGuideLinks(select.value);
}
function updateGuideLinks(lang){
 for(const link of document.querySelectorAll('a[href]')){
  const href=link.getAttribute('href');
  if(!/^(?:index|how-to|ai-latex-guide|formal-request)\.html(?:\?.*)?$/.test(href))continue;
  const path=href.split('?')[0];
  link.setAttribute('href',path+'?lang='+encodeURIComponent(lang));
 }
}
export {DICTIONARIES,applyExtended};

/** Translate only explicit trusted UI string literals; never pass user content. */
export function uiText(key,lang){const chosen=lang||select?.value||'en';return (DICTIONARIES[chosen]||DICTIONARIES.en)[key]||key;}
export function tourPosition(page,total,lang){const language=lang||select?.value||'en';const n=page+1;switch(language){case 'es':return 'Paso '+n+' de '+total;case 'pt-BR':return 'Etapa '+n+' de '+total;case 'zh-Hans':return '第 '+n+' 步，共 '+total+' 步';case 'fr':return 'Étape '+n+' sur '+total;case 'de':return 'Schritt '+n+' von '+total;default:return 'Step '+n+' of '+total;}}

if(typeof globalThis!=='undefined')globalThis.MathLabTranslations={uiText,tourPosition};

/** Interpolate trusted UI templates. Only presentation content may be passed. */
export function uiFormat(key,values={},lang){return uiText(key,lang).replace(/\{([A-Za-z_]+)\}/g,(match,k)=>Object.hasOwn(values,k)?String(values[k]):match);}
